// Node's own resolution rule sends this require to vt2-init-lib's OWN
// node_modules, not the top-level one: a package's private tree is
// searched before its parents'. The two installs are identical in name,
// version and vulnerable export name, and distinguishable only by path.
const dep = require("vt2-vuln-lib");

// A private helper that exists only to share the vulnerable export's
// spelling (RWF-011). Nothing publishes it, nothing calls it, and it is
// declared BEFORE everything real -- so both a same-file bare-name search
// and a "first function in the file" heuristic land here.
function dangerousOp(input) {
  return "decoy:" + input;
}

// The branch that reaches the vulnerable package. Nothing in this file
// calls it: the ONLY way it ever runs is by being this module's exported
// value.
function fastPath(input) {
  return dep.dangerousOp(input);
}

// The branch that does not.
function slowPath(input) {
  return "slow:" + input;
}

// A resolvable local callable whose entire body is a single unconditional
// throw. RWF-016's callee, unchanged.
function bail() {
  throw new Error("fast mode is not supported by this build");
}

// A harmless local callable that turns a function into a registry key. It
// RETURNS NORMALLY, and it never calls anything.
function keyFor(fn) {
  return "handler:" + fn.name;
}

// A second harmless local callable, used only so the element-access probe
// below names something that is neither exported nor part of any branch.
function tag() {
  return "tag";
}

// A plain registry, and the binding the destructuring statement below
// genuinely writes to.
const REGISTRY = {
  "handler:bail": "registered",
  "handler:tag": "registered",
};
let seen;

// ===========================================================================
// THE POISON. This is the entire case.
//
// An ordinary destructuring assignment. It runs on every load, it completes
// normally, and it rebinds exactly ONE local binding: `seen`. `bail` appears
// in it only as an ARGUMENT to `keyFor`, inside a COMPUTED PROPERTY NAME --
// an expression the language evaluates to decide WHICH property of REGISTRY
// to read. A computed key is not an assignment destination.
//
// Nothing about it is near the vulnerable path, and deleting it changes no
// runtime behaviour of this module whatsoever except the value of `seen`.
// ===========================================================================
({ [keyFor(bail)]: seen } = REGISTRY);
void seen;

// The same shape through the other target form -- an ELEMENT-ACCESS index.
// This one rebinds NOTHING local at all: it writes a property of REGISTRY.
// It is the form a corpus scan of real vendored packages actually finds
// (`rollup`, `vite`, `chai`, `esquery` all ship statements like it).
REGISTRY[keyFor(tag)] = "installed";

// A same-name decoy nested inside a function that is never called at module
// scope. Real JS lexical scoping never resolves the module-scope
// destructuring above to this one, and this destructuring never runs at
// load time either -- so it changes no answer.
function configure() {
  function bail() {
    return "safe";
  }
  const local = { "handler:bail": 1 };
  let got;
  ({ [keyFor(bail)]: got } = local);
  return got;
}

// A destructuring statement that GENUINELY rebinds a local callable, at
// module scope, so that this fixture cannot be passed by an analyzer that
// simply stopped recording destructuring targets altogether. `retired` is
// really replaced here, and nothing downstream may treat it as the function
// declared above.
function retired() {
  throw new Error("never used");
}
const REPLACEMENTS = { retired: () => "replaced" };
({ retired } = REPLACEMENTS);
void retired;

if (process.env.VT2_MODE === "fast") {
  module.exports = fastPath;
  // RWF-024's cutoff, unchanged: an object literal's computed keys are
  // evaluated in source order as the literal is constructed, so reaching
  // this declaration necessarily invokes `bail()`, which never returns.
  // `mode` is never bound and module evaluation on this branch ends here.
  //
  // Before RWF-025 this cutoff was silently withdrawn -- not by anything
  // in this block, but by the destructuring statement fifty lines above it,
  // which made `bail`'s identity unresolvable for the WHOLE file.
  const mode = {
    [keyFor(tag)]: "fast",
    [bail()]: 1,
  };
  void mode;
}

// Reached on every OTHER load, and on no load where the branch above was
// taken.
module.exports = slowPath;

void configure;
void tag;
